O exemplo clássico, filtrar números pares:

```
const numeros = [1, 2, 3, 4, 5, 6];

const pares = numeros.filter((n) => n % 2 === 0);
// devolve: [2, 4, 6]
```

E com objetos — o caso do dia a dia:

```
const clientes = [
  { nome: 'Ana', idade: 17 },
  { nome: 'Beto', idade: 22 },
  { nome: 'Caio', idade: 15 }
];

const maiores = clientes.filter((c) => c.idade >= 18);
// devolve: [{ nome: 'Beto', idade: 22 }]
```

Quando NENHUM item passa, o resultado é a lista vazia `[]` — não é erro, é uma resposta válida: "não sobrou ninguém na peneira".

code.code:
const numeros = [1, 2, 3, 4, 5, 6];

const pares = numeros.filter((n) => n % 2 === 0);
console.log(pares);  // [2, 4, 6]

const impares = numeros.filter((n) => n % 2 !== 0);
console.log(impares); // [1, 3, 5]

console.log(numeros.filter((n) => n > 100)); // [] — ninguém passou
console.log(numeros); // [1, 2, 3, 4, 5, 6] — a original continua inteira

// Passo 1: conferimos que veio uma lista de verdade.
function filtrarMaioresDeIdade(clientes) {
  if (!Array.isArray(clientes)) {
    throw new Error('clientes precisa ser uma lista');
  }

  // Passo 2 e 3: filter devolve a lista nova só com quem passou no teste.
  return clientes.filter((cliente) => cliente.idade >= 18);
}

const lista = [
  { nome: 'Ana', idade: 17 },
  { nome: 'Beto', idade: 22 },
  { nome: 'Caio', idade: 15 }
];

console.log(filtrarMaioresDeIdade(lista));
// imprime: [{ nome: 'Beto', idade: 22 }]
